# src/rafeeq/observability/retry.py
"""Bounded retry with backoff -- ONLY for idempotent operations.
Retrying a write tool is the double-refund incident (M1/M3) reborn."""
def call_with_retry(tool_name, fn, *args, retries=2, base=0.5, ledger=None, **kwargs):
    ledger = ledger or DEFAULT_LEDGER
    if tool_name not in IDEMPOTENT:
        result = fn(*args, **kwargs)          # NEVER retry a write tool
        ledger.record(tool_name, 1, "success", idempotent=False)
        return result
    for attempt in range(1, retries + 2):
        try:
            result = fn(*args, **kwargs)
        except TransientToolError as exc:
            ledger.record(tool_name, attempt, "transient_error", True)
            if attempt == retries + 1:
                raise
            time.sleep(base * (2 ** (attempt - 1)))
            continue
        ledger.record(tool_name, attempt, "success", True)
        return result
